&= \frac{\left(r_{1}^{2}+r_{2}^{2}\right)^{2}-2 r_{1}^{2} r_{2}^{2}}{r_{1} r_{2}} \\
&= \frac{\left(\left(r_{1}+r_{2}\right)^{2}-2 r_{1} r_{2}\right)^{2}-2\left(r_{1} r_{2}\right)^{2}}{r_{1} r_{2}} \\
